(function(){var STORAGE_KEY="mwakete_fab_pos";var DRAG_THRESHOLD=6;var EDGE_GAP=12;var fab=null;var startX=0,startY=0;var grabDX=0,grabDY=0;var dragging=false;var moved=false;function bottomReserved(){var nav=document.querySelector(".bottom-nav");if(!nav)return 0;var r=nav.getBoundingClientRect();return r.height>0&&getComputedStyle(nav).position==="fixed"?r.height:0}function topReserved(){var header=document.querySelector(".site-header");if(!header)return 0;var pos=getComputedStyle(header).position;if(pos!=="fixed"&&pos!=="sticky")return 0;return header.getBoundingClientRect().height}function clampBottom(bottom){var h=fab.offsetHeight||56;var min=bottomReserved()+EDGE_GAP;var max=window.innerHeight-h-topReserved()-EDGE_GAP;if(max<min)max=min;return Math.max(min,Math.min(max,bottom))}function save(pos){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(pos))}catch(e){}}function load(){try{var raw=localStorage.getItem(STORAGE_KEY);if(!raw)return null;var p=JSON.parse(raw);if(!p||p.side!=="left"&&p.side!=="right")return null;if(typeof p.bottom!=="number"||!isFinite(p.bottom))return null;return p}catch(e){return null}}function place(pos){var bottom=clampBottom(pos.bottom);fab.style.bottom=bottom+"px";if(pos.side==="left"){fab.style.left=EDGE_GAP+"px";fab.style.right="auto"}else{fab.style.right=EDGE_GAP+"px";fab.style.left="auto"}fab.classList.add("fab-moved");return{side:pos.side,bottom:bottom}}function onPointerDown(e){if(e.button!==undefined&&e.button!==0)return;var r=fab.getBoundingClientRect();startX=e.clientX;startY=e.clientY;grabDX=e.clientX-r.left;grabDY=e.clientY-r.top;dragging=true;moved=false;try{fab.setPointerCapture(e.pointerId)}catch(err){}}function onPointerMove(e){if(!dragging)return;var dx=e.clientX-startX;var dy=e.clientY-startY;if(!moved&&Math.abs(dx)<DRAG_THRESHOLD&&Math.abs(dy)<DRAG_THRESHOLD)return;if(!moved){moved=true;fab.classList.add("is-dragging")}var w=fab.offsetWidth;var h=fab.offsetHeight;var left=Math.max(0,Math.min(window.innerWidth-w,e.clientX-grabDX));var top=Math.max(0,Math.min(window.innerHeight-h,e.clientY-grabDY));fab.style.left=left+"px";fab.style.top=top+"px";fab.style.right="auto";fab.style.bottom="auto";e.preventDefault()}function onPointerUp(e){if(!dragging)return;dragging=false;try{fab.releasePointerCapture(e.pointerId)}catch(err){}if(!moved)return;fab.classList.remove("is-dragging");var r=fab.getBoundingClientRect();var side=r.left+r.width/2<window.innerWidth/2?"left":"right";var bottom=window.innerHeight-r.bottom;fab.style.top="auto";save(place({side:side,bottom:bottom}))}function onDocumentClickCapture(e){if(!moved)return;if(!fab.contains(e.target)&&e.target!==fab)return;moved=false;e.preventDefault();e.stopPropagation()}function init(){fab=document.getElementById("chat-fab");if(!fab||!window.PointerEvent)return;var saved=load();if(saved)place(saved);fab.addEventListener("pointerdown",onPointerDown);fab.addEventListener("pointermove",onPointerMove);fab.addEventListener("pointerup",onPointerUp);fab.addEventListener("pointercancel",function(){dragging=false;moved=false;fab.classList.remove("is-dragging")});document.addEventListener("click",onDocumentClickCapture,true);window.addEventListener("resize",function(){if(!fab.classList.contains("fab-moved"))return;var s=load();if(s)place(s)})}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init)}else{init()}})();